package com.akshay.stockflow.auth;
import jakarta.persistence.*; import org.springframework.security.core.GrantedAuthority; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.UserDetails; import java.time.Instant; import java.util.*;
@Entity @Table(name="user_accounts") public class UserAccount implements UserDetails {
@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String email; @Column(nullable=false) private String passwordHash; @Column(nullable=false) private String fullName; @Enumerated(EnumType.STRING) @Column(nullable=false) private Role role; @Column(nullable=false) private boolean enabled=true; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now();
protected UserAccount(){} public UserAccount(String email,String passwordHash,String fullName,Role role){this.email=email.toLowerCase(Locale.ROOT);this.passwordHash=passwordHash;this.fullName=fullName;this.role=role;}
public Long getId(){return id;} public String getEmail(){return email;} public String getFullName(){return fullName;} public Role getRole(){return role;} public Instant getCreatedAt(){return createdAt;} public void setRole(Role role){this.role=role;} public void setEnabled(boolean enabled){this.enabled=enabled;}
@Override public Collection<? extends GrantedAuthority> getAuthorities(){return List.of(new SimpleGrantedAuthority("ROLE_"+role.name()));} @Override public String getPassword(){return passwordHash;} @Override public String getUsername(){return email;} @Override public boolean isAccountNonExpired(){return true;} @Override public boolean isAccountNonLocked(){return true;} @Override public boolean isCredentialsNonExpired(){return true;} @Override public boolean isEnabled(){return enabled;}
}
